const liczby = [12, 5, 8, 19, 3];
const jestParzysta = n => n % 2 === 0;

console.log(liczby.filter(jestParzysta)); // [12, 8]

const produkty = [
  { name: "Klawiatura", cena: 150 },
  { name: "Mysz", cena: 60 },
  { name: "Monitor", cena: 800 }
];

const jestDrogi = p => p.cena > 100;
console.log(produkty.filter(jestDrogi));
// [{ name: 'Klawiatura', cena: 150 }, { name: 'Monitor', cena: 800 }]

const produkty = [
  { name: "Klawiatura", cena: 150 },
  { name: "Mysz", cena: 60 },
  { name: "Monitor", cena: 800 }
];

const jestTani = p => p.cena <= 100;
console.log(produkty.filter(jestTani)); // [{ name: 'Mysz', cena: 60 }]

function stworzDodawacz(liczba) {
  return wartosc => wartosc + liczba;
}

const dodaj10 = stworzDodawacz(10);
const dodaj100 = stworzDodawacz(100);

console.log(dodaj10(5));   // 15
console.log(dodaj100(5));  // 105

function stworzFormatter(jednostka) {
  return liczba => `${liczba} ${jednostka}`;
}

const formatterKm = stworzFormatter("km");
const formatterKg = stworzFormatter("kg");

console.log(formatterKm(5));  // "5 km"
console.log(formatterKg(70)); // "70 kg"

const imiona = ["Ala", "Bartek", "Celina"];
const dlugosci = imiona.map(imie => imie.length);
console.log(dlugosci); // [3, 6, 6]

function uruchomZWarunkiem(fn, warunek, wartosc) {
  if (warunek(wartosc)) {
    console.log(fn(wartosc));
  } else {
    console.log("pominieto");
  }
}

uruchomZWarunkiem(n => n * 2, n => n > 0, 5);  // 10
uruchomZWarunkiem(n => n * 2, n => n > 0, -5); // "pominieto"

